multi_case.c_draft:
#include <matrixLIB.h>
#include <builtin_MATH.h>
/* Multi-case alias-template C draft.
   Each case-resolved alias is assigned a full source value first;
   the normal structured matrix DAG is generated exactly once. */
/* RTDS-style C draft for structured node elimination.
   RAM math reference may use matrix_Add/Sub/Mul on raw arrays.
   Runtime sections use MATRIX_ matrixDim/register/condition plus set_CODE,
   matrix_mult_CODE, matrix_matXvec_CODE, matrix_add_CODE/subtract_CODE,
   matrix_scalarMult_CODE, MATH_matx_invert,
   mat_2x2_sym_inv_code, mat_3x3_sym_inv_code. See LOCAL_math_builtin_functions.md. */
/* RTDS lifecycle placement for a network with no eliminated internal nodes.
   No Schur complement is required: use the original G matrix and Ihis vector directly. */
STATIC:

    int C1_case_id = 0;
    double G11 = 0.0;
    double G12 = 0.0;
    double G22 = 0.0;
    double Gc = 0.0;
    double IhisC = 0.0;
    double Ihis_p = 0.0;
    double Ihis_s = 0.0;

    /* Runtime matrix objects */
    /* Runtime state */
    int rtds_matrix_code_ready = 0;
    /* User G/CODE symbols */
    double multcase_G_C1_N1_N1 = 0.0;
    double multcase_G_C1_N1_N2 = 0.0;
    double multcase_G_C1_N1_N3 = 0.0;
    double multcase_G_C1_N1_N4 = 0.0;
    double multcase_G_C1_N2_N2 = 0.0;
    double multcase_G_C1_N2_N3 = 0.0;
    double multcase_G_C1_N2_N4 = 0.0;
    double multcase_G_C1_N3_N3 = 0.0;
    double multcase_G_C1_N3_N4 = 0.0;
    double multcase_G_C1_N4_N4 = 0.0;
    /* User Ihis/history symbols */
    double multcase_Ihis_C1_N1 = 0.0;
    double multcase_Ihis_C1_N2 = 0.0;
    double multcase_Ihis_C1_N3 = 0.0;
    double multcase_Ihis_C1_N4 = 0.0;

LOCAL_STATIC:

RAM_PASS1:
    /* Decode the optional global case selector into per-element local cases. */
    switch (case_id) {
    case 0: /* case 0: Custom1 = Trf; C1=case0 */
        C1_case_id = 0;
        break;
    case 1: /* case 1: Custom1 = Trf_leftC; C1=case1 */
        C1_case_id = 1;
        break;
    case 2: /* case 2: Custom1 = Trf_RightC; C1=case2 */
        C1_case_id = 2;
        break;
    case 3: /* case 3: Custom1 = Trf_BothC; C1=case3 */
        C1_case_id = 3;
        break;
    default:
        C1_case_id = 0;
        break;
    }
    int err = 0;
    /* ************************************************************************
     * RAM-SIDE G MATRIX VALUE SETUP
     * No internal nodes are selected, so fixed RAM G stamping uses the original G matrix.
     * Assign or compute every G-related value before writing g_mat_over.
     * Dynamic entries are registered in GVALUES and refreshed in CODE.
     * ************************************************************************ */


    /* Case-conditional RAM final-G stamp. Each init-time case gets its own compact RAM overlay. */
    switch (case_id) {
    case 0:
        /* CODE-owned case: no RAM stamp for varG_c1_p1_c1_p1. */
        /* CODE-owned case: no RAM stamp for varG_c1_p1_c1_p2. */
        /* CODE-owned case: no RAM stamp for varG_c1_p1_c1_p3. */
        /* CODE-owned case: no RAM stamp for varG_c1_p1_c1_p4. */
        /* CODE-owned case: no RAM stamp for varG_c1_p2_c1_p2. */
        /* CODE-owned case: no RAM stamp for varG_c1_p2_c1_p3. */
        /* CODE-owned case: no RAM stamp for varG_c1_p2_c1_p4. */
        /* CODE-owned case: no RAM stamp for varG_c1_p3_c1_p3. */
        /* CODE-owned case: no RAM stamp for varG_c1_p3_c1_p4. */
        /* CODE-owned case: no RAM stamp for varG_c1_p4_c1_p4. */
        /* No RAM-owned final G entries in this case. */
        break;
    case 1:
        g_mat_nods[0] = getNodeNum(comp, "c1_p1");
        g_mat_nods[1] = getNodeNum(comp, "c1_p2");
        g_mat_nods[2] = getNodeNum(comp, "c1_p3");
        g_mat_nods[3] = getNodeNum(comp, "c1_p4");
        for (int row = 0; row < 4; row++) {
            for (int col = 0; col < 4; col++) {
                g_mat_over[row][col] = 0.0;
            }
        }
        g_mat_over[0][0] = -pow(Gc, 2.0)/(G11 + Gc) + Gc;
        g_mat_over[0][1] = -G11*Gc/(G11 + Gc);
        g_mat_over[1][0] = -G11*Gc/(G11 + Gc);
        g_mat_over[0][2] = G12*Gc/(G11 + Gc);
        g_mat_over[2][0] = G12*Gc/(G11 + Gc);
        g_mat_over[0][3] = -G12*Gc/(G11 + Gc);
        g_mat_over[3][0] = -G12*Gc/(G11 + Gc);
        g_mat_over[1][1] = -pow(G11, 2.0)/(G11 + Gc) + G11;
        g_mat_over[1][2] = G11*G12/(G11 + Gc) - G12;
        g_mat_over[2][1] = G11*G12/(G11 + Gc) - G12;
        g_mat_over[1][3] = -G11*G12/(G11 + Gc) + G12;
        g_mat_over[3][1] = -G11*G12/(G11 + Gc) + G12;
        g_mat_over[2][2] = -pow(G12, 2.0)/(G11 + Gc) + G22;
        g_mat_over[2][3] = pow(G12, 2.0)/(G11 + Gc) - G22;
        g_mat_over[3][2] = pow(G12, 2.0)/(G11 + Gc) - G22;
        g_mat_over[3][3] = -pow(G12, 2.0)/(G11 + Gc) + G22;
        setupGMatrix(4);
        break;
    case 2:
        /* CODE-owned case: no RAM stamp for varG_c1_p1_c1_p1. */
        /* CODE-owned case: no RAM stamp for varG_c1_p1_c1_p2. */
        /* CODE-owned case: no RAM stamp for varG_c1_p1_c1_p3. */
        /* CODE-owned case: no RAM stamp for varG_c1_p1_c1_p4. */
        /* CODE-owned case: no RAM stamp for varG_c1_p2_c1_p2. */
        /* CODE-owned case: no RAM stamp for varG_c1_p2_c1_p3. */
        /* CODE-owned case: no RAM stamp for varG_c1_p2_c1_p4. */
        /* CODE-owned case: no RAM stamp for varG_c1_p3_c1_p3. */
        /* CODE-owned case: no RAM stamp for varG_c1_p3_c1_p4. */
        /* CODE-owned case: no RAM stamp for varG_c1_p4_c1_p4. */
        /* No RAM-owned final G entries in this case. */
        break;
    case 3:
        /* CODE-owned case: no RAM stamp for varG_c1_p1_c1_p1. */
        /* CODE-owned case: no RAM stamp for varG_c1_p1_c1_p2. */
        /* CODE-owned case: no RAM stamp for varG_c1_p1_c1_p3. */
        /* CODE-owned case: no RAM stamp for varG_c1_p1_c1_p4. */
        /* CODE-owned case: no RAM stamp for varG_c1_p2_c1_p2. */
        /* CODE-owned case: no RAM stamp for varG_c1_p2_c1_p3. */
        /* CODE-owned case: no RAM stamp for varG_c1_p2_c1_p4. */
        /* CODE-owned case: no RAM stamp for varG_c1_p3_c1_p3. */
        /* CODE-owned case: no RAM stamp for varG_c1_p3_c1_p4. */
        /* CODE-owned case: no RAM stamp for varG_c1_p4_c1_p4. */
        /* No RAM-owned final G entries in this case. */
        break;
    default:
        reportError_RW("network_node", STOP_IMMEDIATELY_CONDITION,
                       "Invalid multi-case case_id %d for component %s.",
                       case_id, Name);
        break;
    }

    if (err > 0) {
        reportError_RW("network_node", STOP_IMMEDIATELY_CONDITION,
                       "RTDS matrix allocation failed for component %s.", Name);
    }

GVALUES:
    /* Dynamic original-G stamp handles, ordered by upper triangle. */
    double varG_c1_p1_c1_p1 = createGValue("varG_c1_p1_c1_p1", "c1_p1", "c1_p1", 0, "case_id == 0 || case_id == 2 || case_id == 3");
    double varG_c1_p1_c1_p2 = createGValue("varG_c1_p1_c1_p2", "c1_p1", "c1_p2", 0, "case_id == 0 || case_id == 2 || case_id == 3");
    double varG_c1_p1_c1_p3 = createGValue("varG_c1_p1_c1_p3", "c1_p1", "c1_p3", 0, "case_id == 0 || case_id == 2 || case_id == 3");
    double varG_c1_p1_c1_p4 = createGValue("varG_c1_p1_c1_p4", "c1_p1", "c1_p4", 0, "case_id == 0 || case_id == 2 || case_id == 3");
    double varG_c1_p2_c1_p2 = createGValue("varG_c1_p2_c1_p2", "c1_p2", "c1_p2", 0, "case_id == 0 || case_id == 2 || case_id == 3");
    double varG_c1_p2_c1_p3 = createGValue("varG_c1_p2_c1_p3", "c1_p2", "c1_p3", 0, "case_id == 0 || case_id == 2 || case_id == 3");
    double varG_c1_p2_c1_p4 = createGValue("varG_c1_p2_c1_p4", "c1_p2", "c1_p4", 0, "case_id == 0 || case_id == 2 || case_id == 3");
    double varG_c1_p3_c1_p3 = createGValue("varG_c1_p3_c1_p3", "c1_p3", "c1_p3", 0, "case_id == 0 || case_id == 2 || case_id == 3");
    double varG_c1_p3_c1_p4 = createGValue("varG_c1_p3_c1_p4", "c1_p3", "c1_p4", 0, "case_id == 0 || case_id == 2 || case_id == 3");
    double varG_c1_p4_c1_p4 = createGValue("varG_c1_p4_c1_p4", "c1_p4", "c1_p4", 0, "case_id == 0 || case_id == 2 || case_id == 3");

CODE:
BEGIN_T0:
    /* Resolve CODE multi-case effective aliases as full values, never deltas. */
    switch (C1_case_id) {
    case 0:
        multcase_G_C1_N1_N1 = G22;
        multcase_G_C1_N1_N2 = G12;
        multcase_G_C1_N1_N3 = G12;
        multcase_G_C1_N1_N4 = G22;
        multcase_G_C1_N2_N2 = G11;
        multcase_G_C1_N2_N3 = G11;
        multcase_G_C1_N2_N4 = G12;
        multcase_G_C1_N3_N3 = G11;
        multcase_G_C1_N3_N4 = G12;
        multcase_G_C1_N4_N4 = G22;
        break;
    case 1:
        multcase_G_C1_N1_N1 = -pow(Gc, 2.0)/(G11 + Gc) + Gc;
        multcase_G_C1_N1_N2 = G11*Gc/(G11 + Gc);
        multcase_G_C1_N1_N3 = G12*Gc/(G11 + Gc);
        multcase_G_C1_N1_N4 = G12*Gc/(G11 + Gc);
        multcase_G_C1_N2_N2 = -pow(G11, 2.0)/(G11 + Gc) + G11;
        multcase_G_C1_N2_N3 = -G11*G12/(G11 + Gc) + G12;
        multcase_G_C1_N2_N4 = -G11*G12/(G11 + Gc) + G12;
        multcase_G_C1_N3_N3 = -pow(G12, 2.0)/(G11 + Gc) + G22;
        multcase_G_C1_N3_N4 = -pow(G12, 2.0)/(G11 + Gc) + G22;
        multcase_G_C1_N4_N4 = -pow(G12, 2.0)/(G11 + Gc) + G22;
        break;
    case 2:
        multcase_G_C1_N1_N1 = G11 - pow(G12, 2.0)/(G22 + Gc);
        multcase_G_C1_N1_N2 = G11 - pow(G12, 2.0)/(G22 + Gc);
        multcase_G_C1_N1_N3 = G12*Gc/(G22 + Gc);
        multcase_G_C1_N1_N4 = -G12*G22/(G22 + Gc) + G12;
        multcase_G_C1_N2_N2 = G11 - pow(G12, 2.0)/(G22 + Gc);
        multcase_G_C1_N2_N3 = G12*Gc/(G22 + Gc);
        multcase_G_C1_N2_N4 = -G12*G22/(G22 + Gc) + G12;
        multcase_G_C1_N3_N3 = -pow(Gc, 2.0)/(G22 + Gc) + Gc;
        multcase_G_C1_N3_N4 = G22*Gc/(G22 + Gc);
        multcase_G_C1_N4_N4 = -pow(G22, 2.0)/(G22 + Gc) + G22;
        break;
    case 3:
        multcase_G_C1_N1_N1 = -pow(G12, 2.0)*pow(Gc, 2.0)/(-pow(G11, 2.0)*pow(G12, 2.0)/(G11 + Gc) + pow(G11, 2.0)*G22 + pow(G11, 2.0)*Gc - 2.0*G11*pow(G12, 2.0)*Gc/(G11 + Gc) + 2.0*G11*G22*Gc + 2.0*G11*pow(Gc, 2.0) - pow(G12, 2.0)*pow(Gc, 2.0)/(G11 + Gc) + G22*pow(Gc, 2.0) + pow(Gc, 3.0)) - pow(Gc, 2.0)/(G11 + Gc) + Gc;
        multcase_G_C1_N1_N2 = G11*pow(G12, 2.0)*Gc/(-pow(G11, 2.0)*pow(G12, 2.0)/(G11 + Gc) + pow(G11, 2.0)*G22 + pow(G11, 2.0)*Gc - 2.0*G11*pow(G12, 2.0)*Gc/(G11 + Gc) + 2.0*G11*G22*Gc + 2.0*G11*pow(Gc, 2.0) - pow(G12, 2.0)*pow(Gc, 2.0)/(G11 + Gc) + G22*pow(Gc, 2.0) + pow(Gc, 3.0)) + G11*Gc/(G11 + Gc) - pow(G12, 2.0)*Gc/(-G11*pow(G12, 2.0)/(G11 + Gc) + G11*G22 + G11*Gc - pow(G12, 2.0)*Gc/(G11 + Gc) + G22*Gc + pow(Gc, 2.0));
        multcase_G_C1_N1_N3 = G12*pow(Gc, 2.0)/(-G11*pow(G12, 2.0)/(G11 + Gc) + G11*G22 + G11*Gc - pow(G12, 2.0)*Gc/(G11 + Gc) + G22*Gc + pow(Gc, 2.0));
        multcase_G_C1_N1_N4 = pow(G12, 3.0)*Gc/(-pow(G11, 2.0)*pow(G12, 2.0)/(G11 + Gc) + pow(G11, 2.0)*G22 + pow(G11, 2.0)*Gc - 2.0*G11*pow(G12, 2.0)*Gc/(G11 + Gc) + 2.0*G11*G22*Gc + 2.0*G11*pow(Gc, 2.0) - pow(G12, 2.0)*pow(Gc, 2.0)/(G11 + Gc) + G22*pow(Gc, 2.0) + pow(Gc, 3.0)) - G12*G22*Gc/(-G11*pow(G12, 2.0)/(G11 + Gc) + G11*G22 + G11*Gc - pow(G12, 2.0)*Gc/(G11 + Gc) + G22*Gc + pow(Gc, 2.0)) + G12*Gc/(G11 + Gc);
        multcase_G_C1_N2_N2 = -pow(G11, 2.0)*pow(G12, 2.0)/(-pow(G11, 2.0)*pow(G12, 2.0)/(G11 + Gc) + pow(G11, 2.0)*G22 + pow(G11, 2.0)*Gc - 2.0*G11*pow(G12, 2.0)*Gc/(G11 + Gc) + 2.0*G11*G22*Gc + 2.0*G11*pow(Gc, 2.0) - pow(G12, 2.0)*pow(Gc, 2.0)/(G11 + Gc) + G22*pow(Gc, 2.0) + pow(Gc, 3.0)) - pow(G11, 2.0)/(G11 + Gc) + 2.0*G11*pow(G12, 2.0)/(-G11*pow(G12, 2.0)/(G11 + Gc) + G11*G22 + G11*Gc - pow(G12, 2.0)*Gc/(G11 + Gc) + G22*Gc + pow(Gc, 2.0)) + G11 - pow(G12, 2.0)/(-pow(G12, 2.0)/(G11 + Gc) + G22 + Gc);
        multcase_G_C1_N2_N3 = -G11*G12*Gc/(-G11*pow(G12, 2.0)/(G11 + Gc) + G11*G22 + G11*Gc - pow(G12, 2.0)*Gc/(G11 + Gc) + G22*Gc + pow(Gc, 2.0)) + G12*Gc/(-pow(G12, 2.0)/(G11 + Gc) + G22 + Gc);
        multcase_G_C1_N2_N4 = -G11*pow(G12, 3.0)/(-pow(G11, 2.0)*pow(G12, 2.0)/(G11 + Gc) + pow(G11, 2.0)*G22 + pow(G11, 2.0)*Gc - 2.0*G11*pow(G12, 2.0)*Gc/(G11 + Gc) + 2.0*G11*G22*Gc + 2.0*G11*pow(Gc, 2.0) - pow(G12, 2.0)*pow(Gc, 2.0)/(G11 + Gc) + G22*pow(Gc, 2.0) + pow(Gc, 3.0)) + G11*G12*G22/(-G11*pow(G12, 2.0)/(G11 + Gc) + G11*G22 + G11*Gc - pow(G12, 2.0)*Gc/(G11 + Gc) + G22*Gc + pow(Gc, 2.0)) - G11*G12/(G11 + Gc) + pow(G12, 3.0)/(-G11*pow(G12, 2.0)/(G11 + Gc) + G11*G22 + G11*Gc - pow(G12, 2.0)*Gc/(G11 + Gc) + G22*Gc + pow(Gc, 2.0)) - G12*G22/(-pow(G12, 2.0)/(G11 + Gc) + G22 + Gc) + G12;
        multcase_G_C1_N3_N3 = -pow(Gc, 2.0)/(-pow(G12, 2.0)/(G11 + Gc) + G22 + Gc) + Gc;
        multcase_G_C1_N3_N4 = -pow(G12, 2.0)*Gc/(-G11*pow(G12, 2.0)/(G11 + Gc) + G11*G22 + G11*Gc - pow(G12, 2.0)*Gc/(G11 + Gc) + G22*Gc + pow(Gc, 2.0)) + G22*Gc/(-pow(G12, 2.0)/(G11 + Gc) + G22 + Gc);
        multcase_G_C1_N4_N4 = -pow(G12, 4.0)/(-pow(G11, 2.0)*pow(G12, 2.0)/(G11 + Gc) + pow(G11, 2.0)*G22 + pow(G11, 2.0)*Gc - 2.0*G11*pow(G12, 2.0)*Gc/(G11 + Gc) + 2.0*G11*G22*Gc + 2.0*G11*pow(Gc, 2.0) - pow(G12, 2.0)*pow(Gc, 2.0)/(G11 + Gc) + G22*pow(Gc, 2.0) + pow(Gc, 3.0)) + 2.0*pow(G12, 2.0)*G22/(-G11*pow(G12, 2.0)/(G11 + Gc) + G11*G22 + G11*Gc - pow(G12, 2.0)*Gc/(G11 + Gc) + G22*Gc + pow(Gc, 2.0)) - pow(G12, 2.0)/(G11 + Gc) - pow(G22, 2.0)/(-pow(G12, 2.0)/(G11 + Gc) + G22 + Gc) + G22;
        break;
    default:
        multcase_G_C1_N1_N1 = G22;
        multcase_G_C1_N1_N2 = G12;
        multcase_G_C1_N1_N3 = G12;
        multcase_G_C1_N1_N4 = G22;
        multcase_G_C1_N2_N2 = G11;
        multcase_G_C1_N2_N3 = G11;
        multcase_G_C1_N2_N4 = G12;
        multcase_G_C1_N3_N3 = G11;
        multcase_G_C1_N3_N4 = G12;
        multcase_G_C1_N4_N4 = G22;
        break;
    }
    /* Resolve CODE_PER_STEP multi-case effective aliases as full values, never deltas. */
    switch (C1_case_id) {
    case 0:
        multcase_Ihis_C1_N1 = Ihis_s;
        multcase_Ihis_C1_N2 = Ihis_p;
        multcase_Ihis_C1_N3 = Ihis_p;
        multcase_Ihis_C1_N4 = Ihis_s;
        break;
    case 1:
        multcase_Ihis_C1_N1 = -Gc*IhisC/(G11 + Gc) + Gc*Ihis_p/(G11 + Gc) + IhisC;
        multcase_Ihis_C1_N2 = G11*IhisC/(G11 + Gc) - G11*Ihis_p/(G11 + Gc) + Ihis_p;
        multcase_Ihis_C1_N3 = G12*IhisC/(G11 + Gc) - G12*Ihis_p/(G11 + Gc) + Ihis_s;
        multcase_Ihis_C1_N4 = G12*IhisC/(G11 + Gc) - G12*Ihis_p/(G11 + Gc) + Ihis_s;
        break;
    case 2:
        multcase_Ihis_C1_N1 = -G12*IhisC/(G22 + Gc) - G12*Ihis_s/(G22 + Gc) + Ihis_p;
        multcase_Ihis_C1_N2 = -G12*IhisC/(G22 + Gc) - G12*Ihis_s/(G22 + Gc) + Ihis_p;
        multcase_Ihis_C1_N3 = Gc*IhisC/(G22 + Gc) + Gc*Ihis_s/(G22 + Gc) - IhisC;
        multcase_Ihis_C1_N4 = -G22*IhisC/(G22 + Gc) - G22*Ihis_s/(G22 + Gc) + Ihis_s;
        break;
